func (e EffectName) String() string { return effectNameTable.name(int(e)) }

// Valid reports whether e is a known EffectName.
func (e EffectName) Valid() bool { return effectNameTable.valid(int(e)) }

// MarshalText implements encoding.TextMarshaler.
func (e EffectName) MarshalText() ([]byte, error) { return effectNameTable.marshal(int(e)) }

// UnmarshalText implements encoding.TextUnmarshaler. Unknown names are
// errors.
func (e *EffectName) UnmarshalText(text []byte) error {
	v, err := effectNameTable.unmarshal(text)
	if err != nil {
		return err
	}
	*e = EffectName(v)
	return nil
}

// ParseEffectName returns the EffectName with the given name.
func ParseEffectName(name string) (EffectName, bool) {
	v, ok := effectNameTable.parse(name)
	return EffectName(v), ok
}

